intent_apply_tick :: proc(d: ^Draw_Intent, logic_hz: i32) -> u64 {
	return u64(max(0, i64(d.at_ms) * i64(logic_hz) / 1000))
}
spawn_tick :: proc(s: ^Spawn_Intent, logic_hz: i32) -> u64 {
	return u64(max(0, i64(s.at_ms) * i64(logic_hz) / 1000))
}
// demolish_apply_tick — the edit fast-path convention (same as a draw): a
// demolish fired at at_ms applies at the NEXT tick boundary (floor + 1), so
// live + replay converge at the step boundary. Demolish is a LOGGED command.
demolish_apply_tick :: proc(d: ^Demolish_Intent, logic_hz: i32) -> u64 {
	return u64(max(0, i64(d.at_ms) * i64(logic_hz) / 1000)) + 1
}
